import (
	"context"
	"fmt"
	"os"

	gowkhtmltopdf "gowkhtmltopdf"
)

func renderPDF() error {
	c := gowkhtmltopdf.NewConverter()

	// Global settings use wkhtmltopdf-style dotted names.
	_ = c.Global().Set("size.pagesize", "A4")
	_ = c.Global().Set("orientation", "Portrait")
	_ = c.Global().Set("margin.top", "15")
	_ = c.Global().Set("title", "Invoice")
	_ = c.Global().Set("outline", "true")

	obj := gowkhtmltopdf.NewObjectSettings().SetPage("invoice.html")

	// Local inputs need the global enable plus the object-side unblock:
	// the upstream-compatible local file ACL pair.
	_ = c.Global().Set("enablelocalfileaccess", "true")
	_ = obj.Set("load.blocklocalfileaccess", "false")
	c.AddObject(obj)

	// Optional callbacks: OnInfo, OnWarn, OnError, OnPhase, OnProgress.
	c.OnPhase = func(phase string) { fmt.Println(phase) }
	c.OnProgress = func(percent int) { fmt.Printf("progress: %d%%\n", percent) }

	if err := c.Convert(context.Background()); err != nil {
		return err
	}
	return os.WriteFile("invoice.pdf", c.Output(), 0o644)
}

func renderPNG() error {
	c := gowkhtmltopdf.NewImageConverter()

	// Image-mode keys: width, height, quality, smartwidth, transparent,
	// format (png or jpg) and the crop.left/crop.top/crop.width/crop.height
	// family.
	_ = c.Set("format", "png")
	_ = c.Set("width", "1024")

	// Local files need the same ACL pair as PDF mode.
	_ = c.Global().Set("enablelocalfileaccess", "true")
	c.AddObject("page.png.html")
	_ = c.Object().Set("load.blocklocalfileaccess", "false")

	if err := c.Convert(context.Background()); err != nil {
		return err
	}
	return os.WriteFile("out.png", c.Output(), 0o644)
}
